BEGIN
    -- step 1 : RTF Check
    DECLARE
        V_RETURN_VALUE VARCHAR2(120);
    BEGIN
        SELECT MAX(PLAN_ID)
          INTO V_RETURN_VALUE
          FROM SCM_MGR.SCP_PLN_RTF_ALLOCATION_V
         WHERE DIVISION_ID = '40'
           AND PLAN_START_YYYYMMDD =
               TO_CHAR(
                   SCM_MGR.FN_NEXT_DAY(SYSDATE, 'MON') - 7 * 1,
                   'YYYYMMDD'
               );

        IF V_RETURN_VALUE IS NULL THEN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                'PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE',
                'ERROR',
                0,
                '40 Final Plan NULL',
                '@v_description',
                SYSDATE
            );

            RAISE_APPLICATION_ERROR(
                -20001,
                'Final Plan Error'
            );
        END IF;
    END;

    -- step 2 : PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE
    SCM_MGR.PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE(
        P_DIVISION_ID     => '40',
        P_CUTOFF_YYYYMMDD => NULL,
        P_CREATION_TYPE   => NULL
    );

    COMMIT;
END;

